 company_ uuid;foreign_company uuid;employee_ uuid;other_employee uuid;w jsonb;second_ jsonb;body_ jsonb;client_ uuid:=gen_random_uuid();d date:=(date_trunc('month',now())+interval '2 months')::date+10;
