 if exists(select 1 from public.planning_wishes where id=wish_) then raise exception 'RLS allowed cross company access';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',manager_,'role','authenticated')::text,true);perform set_config('request.jwt.claim.sub',manager_::text,true);
